class Solution {
public:
    int numBusesToDestination(vector<vector<int>>& routes, int source, int target) {
        if (source == target) return 0;
        unordered_map<int, vector<int>> stop_to_buses;
        int n = routes.size();
        for (int i = 0; i < n; i++) {
            for (int s : routes[i]) stop_to_buses[s].push_back(i);
        }
        if (!stop_to_buses.count(source) || !stop_to_buses.count(target)) return -1;
        queue<pair<int, int>> q;
        vector<bool> visited_buses(n, false);
        unordered_set<int> visited_stops = {source};
        for (int b : stop_to_buses[source]) {
            q.push({b, 1});
            visited_buses[b] = true;
        }
        while (!q.empty()) {
            auto [b, step] = q.front();
            q.pop();
            for (int stop : routes[b]) {
                if (stop == target) return step;
                if (!visited_stops.count(stop)) {
                    visited_stops.insert(stop);
                    for (int nxt_b : stop_to_buses[stop]) {
                        if (!visited_buses[nxt_b]) {
                            visited_buses[nxt_b] = true;
                            q.push({nxt_b, step + 1});
                        }
                    }
                }
            }
        }
        return -1;
    }
};

class Solution {
    public int numBusesToDestination(int[][] routes, int source, int target) {
        if (source == target) return 0;
        Map<Integer, List<Integer>> stopToBuses = new HashMap<>();
        int n = routes.length;
        for (int i = 0; i < n; i++) {
            for (int s : routes[i]) {
                stopToBuses.computeIfAbsent(s, k -> new ArrayList<>()).add(i);
            }
        }
        if (!stopToBuses.containsKey(source) || !stopToBuses.containsKey(target)) return -1;
        Queue<int[]> q = new ArrayDeque<>();
        boolean[] visitedBuses = new boolean[n];
        Set<Integer> visitedStops = new HashSet<>();
        visitedStops.add(source);
        for (int b : stopToBuses.get(source)) {
            q.add(new int[]{b, 1});
            visitedBuses[b] = true;
        }
        while (!q.isEmpty()) {
            int[] cur = q.poll();
            int b = cur[0], step = cur[1];
            for (int stop : routes[b]) {
                if (stop == target) return step;
                if (!visitedStops.contains(stop)) {
                    visitedStops.add(stop);
                    for (int nxtB : stopToBuses.get(stop)) {
                        if (!visitedBuses[nxtB]) {
                            visitedBuses[nxtB] = true;
                            q.add(new int[]{nxtB, step + 1});
                        }
                    }
                }
            }
        }
        return -1;
    }
}

var numBusesToDestination = function(routes, source, target) {
    if (source === target) return 0;
    const stopToBuses = new Map();
    const n = routes.length;
    for (let i = 0; i < n; i++) {
        for (const s of routes[i]) {
            if (!stopToBuses.has(s)) stopToBuses.set(s, []);
            stopToBuses.get(s).push(i);
        }
    }
    if (!stopToBuses.has(source) || !stopToBuses.has(target)) return -1;
    const q = [];
    const visitedBuses = new Array(n).fill(false);
    const visitedStops = new Set([source]);
    for (const b of stopToBuses.get(source)) {
        q.push([b, 1]);
        visitedBuses[b] = true;
    }
    while (q.length > 0) {
        const [b, step] = q.shift();
        for (const stop of routes[b]) {
            if (stop === target) return step;
            if (!visitedStops.has(stop)) {
                visitedStops.add(stop);
                for (const nxtB of stopToBuses.get(stop)) {
                    if (!visitedBuses[nxtB]) {
                        visitedBuses[nxtB] = true;
                        q.push([nxtB, step + 1]);
                    }
                }
            }
        }
    }
    return -1;
};
